	private BirdModels() {
	}

	public static TexturedModelData get(String model) {
		return switch (model) {
			case "songbird" -> songbird();
			case "waterfowl" -> waterfowl();
			case "owl" -> owl();
			case "wader" -> wader();
			case "corvid" -> corvid();
			case "woodpecker" -> woodpecker();
			case "seagull" -> seagull();
			default -> throw new IllegalArgumentException("no bird model " + model);
		};
	}

